class Solution { public:int maximumInvitations(vector<int>& favorite){int n=favorite.size();vector<int> indegree(n),depth(n,1);for(int value:favorite)++indegree[value];queue<int> pending;for(int i=0;i<n;++i)if(!indegree[i])pending.push(i);while(!pending.empty()){int node=pending.front();pending.pop();int next=favorite[node];depth[next]=max(depth[next],depth[node]+1);if(!--indegree[next])pending.push(next);}int pairSum=0,longestCycle=0;vector<bool> seen(n);for(int start=0;start<n;++start)if(indegree[start]&&!seen[start]){int length=0,node=start;do{seen[node]=true;++length;node=favorite[node];}while(node!=start);if(length==2)pairSum+=depth[start]+depth[favorite[start]];else longestCycle=max(longestCycle,length);}return max(pairSum,longestCycle);} };
